// === Expandir lista de URLs ===
const P = $json || {};
const urls = Array.isArray(P.dns_urls) ? P.dns_urls : [];

function normalizeUrl(raw) {
  const s = String(raw || '').trim();
  if (!s) return null;

  // Parser manual para evitar dependencia de URL() en este entorno
  const m = s.match(/^(https?):\/\/([^\/:?#]+)(?::(\d+))?(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i);

  if (!m) {
    return {
      original_url: s,
      url: s,
      scheme: null,
      hostname: null,
      port: null,
      path: null,
      check_target: null,
      certificate_key: `invalid::${s}`,
      parse_error: 'Formato de URL no soportado o inválido'
    };
  }

  const scheme = String(m[1] || '').toLowerCase();
  const hostname = String(m[2] || '').toLowerCase();
  const explicitPort = m[3] ? Number(m[3]) : null;
  const port = explicitPort || (scheme === 'https' ? 443 : scheme === 'http' ? 80 : null);
  const pathname = m[4] || '/';
  const search = m[5] || '';
  const hash = m[6] || '';
  const path = `${pathname}${search}${hash}`;

  return {
    original_url: s,
    url: s,
    scheme,
    hostname,
    port,
    path,
    check_target: `${hostname}:${port}`,
    certificate_key: `${scheme}://${hostname}:${port}`
  };
}

return urls
  .map(normalizeUrl)
  .filter(Boolean)
  .map(row => ({ json: row }));

const tls = require('tls');

const items = $input.all().map((i) => i.json || {});
const timeoutMs = 20000;
const concurrency = 15;

function emit(src, status, extra = {}) {
  const url = src.url || src.original_url || '';
  const hostname = src.hostname || '';
  const port = src.port ?? '';
  const lines = [
    `STATUS=${status}`,
    `URL=${url}`,
    `HOST=${hostname}`,
    `PORT=${port}`,
  ];
  for (const [k, v] of Object.entries(extra)) {
    if (v == null || v === '') continue;
    lines.push(`${k}=${v}`);
  }
  return { ...src, stdout: lines.join('\n') };
}

function checkOne(src) {
  const url = src.url || src.original_url || '';
  const hostname = src.hostname || '';
  const port = src.port || null;
  const scheme = src.scheme || null;

  if (!scheme || !hostname || !port) {
    return Promise.resolve(emit(src, 'INVALID_URL'));
  }
  if (scheme !== 'https') {
    return Promise.resolve(emit(src, 'NO_HTTPS'));
  }

  return new Promise((resolve) => {
    let settled = false;
    let socket;

    const finish = (status, extra) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try { socket?.destroy(); } catch {}
      resolve(emit(src, status, extra));
    };

    const timer = setTimeout(() => finish('ERROR', { RC: 'timeout' }), timeoutMs);

    try {
      socket = tls.connect(
        {
          host: hostname,
          port: Number(port),
          servername: hostname,
          rejectUnauthorized: false,
        },
        () => {
          const cert = socket.getPeerCertificate();
          socket.end();

          if (!cert || !cert.valid_to) {
            finish('ERROR', { RC: 'no_cert' });
            return;
          }

          const issuer = cert.issuer && typeof cert.issuer === 'object'
            ? Object.entries(cert.issuer).filter(([, v]) => v).map(([k, v]) => `${k}=${v}`).join(', ')
            : '';
          const subject = cert.subject && typeof cert.subject === 'object'
            ? Object.entries(cert.subject).filter(([, v]) => v).map(([k, v]) => `${k}=${v}`).join(', ')
            : '';

          finish('OK', {
            notAfter: cert.valid_to,
            issuer,
            subject,
          });
        }
      );

      socket.on('error', (err) => finish('ERROR', { RC: String(err?.message || err) }));
    } catch (err) {
      finish('ERROR', { RC: String(err?.message || err) });
    }
  });
}

async function mapPool(list, limit, fn) {
  const results = new Array(list.length);
  let next = 0;
  async function worker() {
    while (next < list.length) {
      const idx = next++;
      results[idx] = await fn(list[idx]);
    }
  }
  const workers = Array.from({ length: Math.min(limit, list.length) }, () => worker());
  await Promise.all(workers);
  return results;
}

const rows = await mapPool(items, concurrency, checkOne);
return rows.map((json) => ({ json }));

// === Parsear salida de openssl y clasificar estado ===
const P = $item(0).$node["Set - Params"].json || {};
const threshold = Number(P.alert_threshold_days || 15);

function parseStdout(raw) {
  const txt = String(raw || '');
  const out = {};
  for (const line of txt.split(/\r?\n/)) {
    if (!line || !line.includes('=')) continue;
    const idx = line.indexOf('=');
    const key = line.slice(0, idx).trim();
    const value = line.slice(idx + 1).trim();
    out[key] = value;
  }
  return out;
}

function toIsoOrNull(v) {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString();
}

function daysRemaining(expiresAtIso) {
  if (!expiresAtIso) return null;
  const now = new Date();
  const exp = new Date(expiresAtIso);
  const diffMs = exp.getTime() - now.getTime();
  return Math.floor(diffMs / 86400000);
}

return $input.all().map(item => {
  const src = item.json || {};
  const parsed = parseStdout(src.stdout || '');

  const url = parsed.URL || src.url || src.original_url || null;
  const hostname = parsed.HOST || src.hostname || null;
  const port = parsed.PORT ? Number(parsed.PORT) : (src.port ?? null);
  const scheme = src.scheme || (url && String(url).startsWith('https://') ? 'https' : url && String(url).startsWith('http://') ? 'http' : null);

  const openssl_status = parsed.STATUS || 'UNKNOWN';
  const issuer = parsed.issuer || null;
  const subject = parsed.subject || null;
  const expires_at = toIsoOrNull(parsed.notAfter || null);
  const days_remaining = daysRemaining(expires_at);

  let state = 'INFO';
  let severity = 'info';
  let reason = 'Sin clasificación.';

  if (scheme !== 'https') {
    state = 'INFO';
    severity = 'info';
    reason = 'URL no HTTPS; no aplica validación de certificado TLS.';
  } else if (openssl_status !== 'OK') {
    state = 'ALERT';
    severity = 'high';
    reason = 'No se pudo leer o validar el certificado.';
  } else if (days_remaining == null) {
    state = 'ALERT';
    severity = 'high';
    reason = 'No se pudo determinar la fecha de expiración.';
  } else if (days_remaining < 0) {
    state = 'ALERT';
    severity = 'critical';
    reason = 'Certificado vencido.';
  } else if (days_remaining <= threshold) {
    state = 'ALERT';
    severity = 'high';
    reason = `Certificado dentro del umbral de ${threshold} días.`;
  } else {
    state = 'OK';
    severity = 'info';
    reason = 'Certificado vigente.';
  }

  return {
    json: {
      url,
      hostname,
      port,
      scheme,
      certificate_key: scheme && hostname && port ? `${scheme}://${hostname}:${port}` : `unknown://${hostname || 'unknown'}:${port || 'unknown'}`,
      openssl_status,
      issuer,
      subject,
      expires_at,
      days_remaining,
      state,
      severity,
      reason,
      threshold_days: threshold,
      checked_at_utc: new Date().toISOString()
    }
  };
});

// === Estado global + recovery parcial/total por URL ===
const P = $item(0).$node["Set - Params"].json || {};
const rows = $items("Function – Parse cert result").map(i => i.json);

const isAlert = (r) => String(r.state || '').toUpperCase() === 'ALERT';
const alerts = rows.filter(isAlert);
const oks = rows.filter(r => String(r.state || '').toUpperCase() === 'OK');
const infos = rows.filter(r => String(r.state || '').toUpperCase() === 'INFO');

const staticData = $getWorkflowStaticData('global');

// Limpiar residuos del bug openssl (days_remaining null / falsos ALERT masivos)
if (!staticData.stateVersion || staticData.stateVersion < 3) {
  staticData.items = {};
  staticData.recovered = {};
  staticData.last_state = 'INIT';
  staticData.stateVersion = 3;
}

const last_state = staticData.last_state || 'INIT';
const state = alerts.length > 0 ? 'ALERT' : 'OK';

const getKey = (r) => r.certificate_key || r.url || `${r.hostname}:${r.port}`;

staticData.items = staticData.items || {};
staticData.recovered = staticData.recovered || {};

const prevItems = staticData.items;
const recoveredMap = staticData.recovered;
const currentAlertSet = {};

// Solo guardar metadatos livianos (evitar que el staticData crezca y falle al persistir)
for (const r of alerts) {
  const k = getKey(r);
  if (!k) continue;
  currentAlertSet[k] = true;
  prevItems[k] = {
    certificate_key: k,
    url: r.url || null,
    hostname: r.hostname || null,
    port: r.port ?? null,
    state: 'ALERT',
    reason: r.reason || null,
    days_remaining: r.days_remaining ?? null,
    expires_at: r.expires_at || null,
    issuer: r.issuer || null,
    threshold_days: r.threshold_days ?? null,
  };
  if (recoveredMap[k]) delete recoveredMap[k];
}

const recovered_items = [];
for (const [k, lastRow] of Object.entries(prevItems)) {
  if (currentAlertSet[k]) continue;

  // Si ya se notificó recovery de esta key, no repetir
  if (!recoveredMap[k]) {
    recovered_items.push({
      ...lastRow,
      _recovery: true,
      recovered_at_utc: new Date().toISOString(),
    });
    recoveredMap[k] = 1;
  }
  delete prevItems[k];
}

const send_alert = alerts.length > 0;
const send_recovery_global = (last_state === 'ALERT' && state === 'OK');
const send_recovery_partial = (!send_recovery_global && recovered_items.length > 0 && last_state === 'ALERT');

// Persistir estado ACTUAL al final (después de calcular transición)
staticData.last_state = state;

// Si recuperamos todo, limpiar mapa recovered para no acumular basura
if (state === 'OK') {
  staticData.items = {};
  // Mantener recoveredMap solo esta corrida; en OK total se limpia para no crecer infinito
  // No limpiar recovered en recovery global: evita re-notificar los mismos fantasmas
  if (Object.keys(recoveredMap).length > 500) {
    staticData.recovered = {};
  }
}

const ts_utc = new Date().toISOString();

return [{
  json: {
    workflow_name: P.workflow_name || 'Monitoreo Certificados TLS/SSL – DNS',
    ts_utc,
