  const s = String(issuer || '').trim();
  if (!s) return 'N/D';

  const cnMatch = s.match(/CN=([^,]+)/i);
  if (cnMatch) return cnMatch[1].trim();

  const oMatch = s.match(/O=([^,]+)/i);
  if (oMatch) return oMatch[1].trim();

  return s;
}

