// === Payload Teams RECOVERY ===
const j = $json;
const recovered = j.recovered_items || [];
const stillAlerts = j.alerts || [];

if (!recovered.length && !j.send_recovery_global) return [];

const global = !!j.send_recovery_global;
const title = global
  ? 'RECOVERY TOTAL – Certificados TLS/SSL'
  : 'RECOVERY PARCIAL – Certificados TLS/SSL';

function formatUtc(iso) {
  if (!iso) return 'N/D';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return 'N/D';
  return d.toISOString().replace('T', ' ').substring(0, 19) + ' UTC';
}

const separator = '\n\n────────────────────\n\n';

const recoveredLines = recovered.length
  ? recovered.map(r => {
      const exp = formatUtc(r.expires_at);
      return [
        `• **URL:** ${r.url || 'N/D'}`,
        `  • Host: ${r.hostname || '-'}:${r.port || '-'}`,
        `  • Expira: ${exp}`,
      ].join('\n');
    }).join(separator)
  : (global
      ? '- Todas las URLs que estaban en alerta se recuperaron.'
      : '- Sin elementos recuperados individuales.');

const pendingLines = stillAlerts.length
  ? stillAlerts.map(r =>
      `• **URL:** ${r.url || 'N/D'} • ${r.reason || r.state || 'N/D'} • días restantes: **${r.days_remaining ?? 'N/D'}**`
    ).join(separator)
  : '- No quedan URLs en alerta.';

const intro = global
  ? '🟢 **Recovery total:** todas las URLs que venían en alerta ya salieron del estado de riesgo.'
  : '🟡 **Recovery parcial:** algunas URLs salieron de alerta, pero todavía quedan otras pendientes.';

return [{ json: { body: toAdaptiveCardBody(messageCardToText({
    "@type": "MessageCard",
    "@context": "https://schema.org/extensions",
    themeColor: global ? "2E8B57" : "F39C12",
    summary: title,
    title,
    sections: [
      {
        markdown: true,
        text:
          `${intro}\n\n` +
          `Hora UTC: ${j.ts_utc}\n` +
          `Recuperadas: **${recovered.length}**\n` +
          `Aún en alerta: **${stillAlerts.length}**`
      },
      {
        markdown: true,
        text: `✅ **Recuperadas**\n\n${recoveredLines}`
      },
      {
        markdown: true,
        text: `📌 **Aún en alerta**\n\n${pendingLines}`
      }
    ]
  }
)) } }];
